public class InnerRouterInputContentQualityAnalysisFeatureConfigurationFactory(Action<Humidifier.MediaConnect.RouterInputTypes.ContentQualityAnalysisFeatureConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaConnect.RouterInputTypes.ContentQualityAnalysisFeatureConfiguration>
{

    internal InnerRouterInputBlackFramesConfigurationFactory BlackFramesFactory { get; set; }

    internal InnerRouterInputSilentAudioConfigurationFactory SilentAudioFactory { get; set; }

    internal InnerRouterInputFrozenFramesConfigurationFactory FrozenFramesFactory { get; set; }

    protected override Humidifier.MediaConnect.RouterInputTypes.ContentQualityAnalysisFeatureConfiguration Create()
    {
        var contentQualityAnalysisFeatureConfigurationResult = CreateContentQualityAnalysisFeatureConfiguration();
        factoryAction?.Invoke(contentQualityAnalysisFeatureConfigurationResult);

        return contentQualityAnalysisFeatureConfigurationResult;
    }

    private Humidifier.MediaConnect.RouterInputTypes.ContentQualityAnalysisFeatureConfiguration CreateContentQualityAnalysisFeatureConfiguration()
    {
        var contentQualityAnalysisFeatureConfigurationResult = new Humidifier.MediaConnect.RouterInputTypes.ContentQualityAnalysisFeatureConfiguration();

        return contentQualityAnalysisFeatureConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaConnect.RouterInputTypes.ContentQualityAnalysisFeatureConfiguration result)
    {
        base.CreateChildren(result);

        result.BlackFrames ??= BlackFramesFactory?.Build();
        result.SilentAudio ??= SilentAudioFactory?.Build();
        result.FrozenFrames ??= FrozenFramesFactory?.Build();
    }

} // End Of Class

